diff --git a/app/api/chat/route.ts b/app/api/chat/route.ts
index 94c3bbb62f263383eb4faf038c8afc90c671e19f..ed69d5444bdf43cd5b82658ec5017bbed642d725 100644
--- a/app/api/chat/route.ts
+++ b/app/api/chat/route.ts
@@ -1,10 +1,6 @@
 import { kv } from "@vercel/kv";
 import { Ratelimit } from "@upstash/ratelimit";
 import { OpenAI } from "openai";
-import {
-  OpenAIStream,
-  StreamingTextResponse,
-} from "ai";
 import { functions, runFunction } from "./functions";

 // Create an OpenAI API client (that's edge friendly!)
@@ -44,29 +40,78 @@ export async function POST(req: Request) {

   const { messages } = await req.json();

-  // check if the conversation requires a function call to be made
+  // Collect complete tool arguments before executing any functions.
   const initialResponse = await openai.chat.completions.create({
-    model: "gpt-3.5-turbo-0613",
+    model: "gpt-5.6-terra",
     messages,
+    stream: false,
+    tools: functions.map((fn) => ({
+      type: "function" as const,
+      function: fn,
+    })),
+    tool_choice: "auto",
+  });
+
+  const message = initialResponse.choices[0]?.message;
+  if (!message) {
+    return new Response("No response from the model.", { status: 502 });
+  }
+
+  const headers = { "Content-Type": "text/plain; charset=utf-8" };
+  if (!message.tool_calls?.length) {
+    return new Response(message.content ?? "", { headers });
+  }
+
+  const toolResults: OpenAI.Chat.Completions.ChatCompletionToolMessageParam[] = [];
+  for (const call of message.tool_calls) {
+    if (call.type !== "function") {
+      return new Response("Unsupported tool call.", { status: 502 });
+    }
+    const result = await runFunction(
+      call.function.name,
+      JSON.parse(call.function.arguments),
+    );
+    toolResults.push({
+      role: "tool",
+      tool_call_id: call.id,
+      content: typeof result === "string" ? result : JSON.stringify(result) ?? "null",
+    });
+  }
+
+  const completion = await openai.chat.completions.create({
+    model: "gpt-5.6-terra",
     stream: true,
-    functions,
-    function_call: "auto",
+    messages: [...messages, message, ...toolResults],
   });

-  const stream = OpenAIStream(initialResponse, {
-    experimental_onFunctionCall: async (
-      { name, arguments: args },
-      createFunctionCallMessages,
-    ) => {
-      const result = await runFunction(name, args);
-      const newMessages = createFunctionCallMessages(result);
-      return openai.chat.completions.create({
-        model: "gpt-3.5-turbo-0613",
-        stream: true,
-        messages: [...messages, ...newMessages],
-      });
+  // Keep the plain-text streaming protocol expected by the existing client,
+  // without relying on the legacy SDK-specific stream adapter.
+  const encoder = new TextEncoder();
+  const iterator = completion[Symbol.asyncIterator]();
+  const stream = new ReadableStream<Uint8Array>({
+    async pull(controller) {
+      try {
+        while (true) {
+          const { value, done } = await iterator.next();
+          if (done) {
+            controller.close();
+            return;
+          }
+          const text = value.choices[0]?.delta.content;
+          if (text) {
+            controller.enqueue(encoder.encode(text));
+            return;
+          }
+        }
+      } catch (error) {
+        controller.error(error);
+      }
+    },
+    async cancel() {
+      completion.controller.abort();
+      await iterator.return?.();
     },
   });

-  return new StreamingTextResponse(stream);
+  return new Response(stream, { headers });
 }
