diff --git a/lib/assistantConfig.ts b/lib/assistantConfig.ts
new file mode 100644
index 0000000000000000000000000000000000000000..15ad607cad2a9a624acef06009305585483660be
--- /dev/null
+++ b/lib/assistantConfig.ts
@@ -0,0 +1,61 @@
+import { createHmac, timingSafeEqual } from 'node:crypto';
+
+export interface AssistantConfig {
+  version: 1;
+  name: string;
+  instructions: string;
+  model: 'gpt-5.6-sol' | 'gpt-5.6-terra';
+  vectorStoreId?: string;
+}
+
+// Accept existing saved model selections, but never send their retired IDs.
+export function normalizeAssistantModel(model: unknown): AssistantConfig['model'] {
+  switch (model) {
+    case 'gpt-4':
+    case 'gpt-4-1106-preview':
+    case 'gpt-5.6-sol':
+      return 'gpt-5.6-sol';
+    case 'gpt-3.5-turbo-1106':
+    case 'gpt-5.6-terra':
+      return 'gpt-5.6-terra';
+    default:
+      throw new Error('Unsupported assistant model');
+  }
+}
+
+function signature(payload: string): Buffer {
+  const key = process.env.ASSISTANT_CONFIG_SECRET || process.env.OPENAI_API_KEY;
+  if (!key) throw new Error('Missing assistant configuration signing key');
+  return createHmac('sha256', key).update('assistant-config-v1.' + payload).digest();
+}
+
+// A signed configuration is durable across serverless instances and needs no
+// mutable in-memory assistant registry. It is authenticated, not encrypted.
+export function encodeAssistant(config: AssistantConfig): string {
+  const payload = Buffer.from(JSON.stringify(config)).toString('base64url');
+  return `cfg1.${payload}.${signature(payload).toString('base64url')}`;
+}
+
+export function decodeAssistant(id: unknown): AssistantConfig {
+  if (typeof id !== 'string' || id.length > 200000) {
+    throw new Error('Invalid assistant configuration');
+  }
+  const [prefix, payload, mac, extra] = id.split('.');
+  if (prefix !== 'cfg1' || !payload || !mac || extra !== undefined) {
+    throw new Error('Please recreate this assistant to use the Responses API');
+  }
+  const supplied = Buffer.from(mac, 'base64url');
+  const expected = signature(payload);
+  if (supplied.length !== expected.length || !timingSafeEqual(supplied, expected)) {
+    throw new Error('Invalid assistant configuration signature');
+  }
+  const config = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as AssistantConfig;
+  if (config.version !== 1 || typeof config.name !== 'string' ||
+      typeof config.instructions !== 'string' ||
+      (config.model !== 'gpt-5.6-sol' && config.model !== 'gpt-5.6-terra') ||
+      (config.vectorStoreId !== undefined &&
+        (typeof config.vectorStoreId !== 'string' || !config.vectorStoreId.startsWith('vs_')))) {
+    throw new Error('Invalid assistant configuration');
+  }
+  return config;
+}
