+import { createRun } from './createRun.js';
+
+export async function handleRunToolCalls(
+    run: OpenAI.Responses.Response,
+    client: OpenAI,
+    conversation: Conversation,
+    assistant: AssistantConfig
+): Promise<OpenAI.Responses.Response> {
+    const toolOutputs: OpenAI.Responses.ResponseInput = [];
+
+    for (const tool of run.output) {
+        if (tool.type !== 'function_call') continue;
+
+        let output: string;
+        try {
+            const toolConfig = Object.prototype.hasOwnProperty.call(tools, tool.name)
+                ? tools[tool.name]
+                : undefined;
+            if (!toolConfig) throw new Error(`Tool ${tool.name} not found`);
