diff --git a/lib/openai-text-stream.ts b/lib/openai-text-stream.ts
new file mode 100644
index 0000000000000000000000000000000000000000..a1893096c97d6ab37e36c3a6f6ae1204bf6d92ec
--- /dev/null
+++ b/lib/openai-text-stream.ts
@@ -0,0 +1,35 @@
+import type { ChatCompletionChunk } from 'openai/resources/chat/completions';
+
+// Preserve the plain-text streaming protocol without the legacy AI SDK's
+// dependency on OpenAI SDK v4 stream types.
+export function openAITextResponse(chunks: AsyncIterable<ChatCompletionChunk>): Response {
+  const iterator = chunks[Symbol.asyncIterator]();
+  const encoder = new TextEncoder();
+  const stream = new ReadableStream<Uint8Array>({
+    async pull(controller) {
+      try {
+        while (true) {
+          const result = await iterator.next();
+          if (result.done) {
+            controller.close();
+            return;
+          }
+          const text = result.value.choices[0]?.delta.content;
+          if (text) {
+            controller.enqueue(encoder.encode(text));
+            return;
+          }
+        }
+      } catch (error) {
+        controller.error(error);
+      }
+    },
+    async cancel() {
+      await iterator.return?.();
+    },
+  });
+
+  return new Response(stream, {
+    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
+  });
+}
