diff --git a/test/openai-migration.test.ts b/test/openai-migration.test.ts
new file mode 100644
index 0000000000000000000000000000000000000000..fbb0cea82fcf3521a5af65550d3a14bd9615b096
--- /dev/null
+++ b/test/openai-migration.test.ts
@@ -0,0 +1,84 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtemp, readFile, writeFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import * as path from 'node:path';
+import type OpenAI from 'openai';
+import { transcribeAudio } from '../src/act/transcribe';
+import { transcribeAudio as transcribeAudioCopy } from '../src/act/transcribe copy';
+import { processAnalysis } from '../src/act/analyze';
+
+for (const [label, transcribe] of [
+  ['primary', transcribeAudio],
+  ['copy', transcribeAudioCopy],
+] as const) {
+  test(`${label} transcription requests JSON and persists its text`, async () => {
+    const directory = await mkdtemp(path.join(tmpdir(), 'transcription-test-'));
+    try {
+      const input = path.join(directory, 'recording.mp3');
+      await writeFile(input, 'mock audio');
+      let requests = 0;
+      const client = {
+        audio: {
+          transcriptions: {
+            async create(params: any) {
+              requests++;
+              assert.equal(params.model, 'gpt-transcribe');
+              assert.equal(params.language, 'en');
+              assert.equal(params.response_format, 'json');
+              const chunks: Buffer[] = [];
+              for await (const chunk of params.file) chunks.push(Buffer.from(chunk));
+              assert.equal(Buffer.concat(chunks).toString(), 'mock audio');
+              return { text: 'Transcribed text.' };
+            },
+          },
+        },
+      } as unknown as OpenAI;
+      const result = await transcribe(client, input);
+      assert.equal(result.text, 'Transcribed text.');
+      assert.equal(await readFile(result.path, 'utf8'), result.text);
+      await transcribe(client, input);
+      assert.equal(requests, 1, 'existing transcription is reused');
+    } finally {
+      await rm(directory, { recursive: true, force: true });
+    }
+  });
+}
+
+test('analysis uses stable structured parsing and preserves the output contract', async () => {
+  const directory = await mkdtemp(path.join(tmpdir(), 'analysis-test-'));
+  try {
+    const parsed = {
+      title: 'Meeting',
+      tools: ['TypeScript'],
+      topics: ['Planning'],
+      actionables: ['Ship'],
+      short_summary: 'Plan agreed.',
+      long_summary: 'The team agreed on a plan.',
+    };
+    let requests = 0;
+    const client = {
+      chat: {
+        completions: {
+          async parse(params: any, options: any) {
+            requests++;
+            assert.equal(params.model, 'gpt-6-luna');
+            assert.equal(params.response_format.type, 'json_schema');
+            assert.equal(params.response_format.json_schema.strict, true);
+            assert.equal(params.response_format.json_schema.name, 'analysis_response');
+            assert.equal(options.timeout, 60_000);
+            return { choices: [{ message: { parsed } }] };
+          },
+        },
+      },
+    } as unknown as OpenAI;
+    const input = path.join(directory, 'meeting_transcription.txt');
+    await processAnalysis(client, 'Meeting transcript', input);
+    const output = JSON.parse(await readFile(path.join(directory, 'meeting_analysis.json'), 'utf8'));
+    assert.deepEqual(output, { ...parsed, transcript: 'Meeting transcript' });
+    await processAnalysis(client, 'Meeting transcript', input);
+    assert.equal(requests, 1, 'existing analysis is reused');
+  } finally {
+    await rm(directory, { recursive: true, force: true });
+  }
+});

