@@ -0,0 +1,79 @@
+import { AssistantService } from './assistant.service';
+
+// Exercise response handling without constructing external service clients.
+describe('Assistant Responses migration', () => {
+  let service: any;
+  let create: jest.Mock;
+
+  beforeEach(() => {
+    service = Object.create(AssistantService.prototype);
+    create = jest.fn().mockResolvedValue({
+      status: 'completed',
+      output: [],
+      output_text: '{"indices":[1]}',
+    });
+    service.openai = {
+      conversations: {
+        create: jest.fn().mockResolvedValue({ id: 'conv_test' }),
+      },
+      responses: { create },
+    };
+  });
+
+  it('uses a fresh conversation and parses response text', async () => {
+    await expect(service.requestJson('data', 'Return JSON')).resolves.toEqual({ indices: [1] });
+    await service.requestJson('other data', 'Return JSON');
+    expect(service.openai.conversations.create).toHaveBeenCalledTimes(2);
+    expect(create).toHaveBeenCalledWith(expect.objectContaining({
+      model: 'gpt-4o',
+      conversation: 'conv_test',
+      input: [{ role: 'user', content: 'data' }],
+      text: { format: { type: 'json_object' } },
+      stream: false,
+    }));
+  });
+
+  it('returns original selected records', async () => {
+    const items = [{ id: 'first' }, { id: 'second' }];
+    const selected = await service.selectItems(items, 'data', 'Select', 1);
+    expect(selected).toEqual([items[1]]);
+    expect(selected[0]).toBe(items[1]);
+  });
+
+  it.each([
+    '{"indices":[2]}',
+    '{"indices":[-1]}',
+    '{"indices":[0.5]}',
+    '{"indices":["0"]}',
+    '{"indices":[0,0]}',
+    '{"indices":[0,1]}',
+    '{"indices":null}',
+  ])('rejects invalid selections: %s', async (output_text) => {
+    create.mockResolvedValue({ status: 'completed', output: [], output_text });
+    await expect(service.selectItems([{}, {}], 'data', 'Select', 1)).rejects.toThrow('Invalid AI selection');
+  });
+
+  it('does not call the provider for an empty selection list', async () => {
+    await expect(service.selectItems([], 'data', 'Select')).resolves.toEqual([]);
+    expect(create).not.toHaveBeenCalled();
+  });
+
+  it.each(['incomplete', 'failed', 'queued'])('rejects a %s response', async (status) => {
+    create.mockResolvedValue({ status, output: [], output_text: '{}' });
+    await expect(service.requestJson('data', 'Return JSON')).rejects.toThrow('did not complete');
+  });
+
+  it.each(['', 'not JSON', '[]', 'null'])('rejects unusable output: %s', async (output_text) => {
+    create.mockResolvedValue({ status: 'completed', output: [], output_text });
+    await expect(service.requestJson('data', 'Return JSON')).rejects.toThrow();
+  });
+
+  it('rejects refusals rather than attempting to parse them', async () => {
+    create.mockResolvedValue({
+      status: 'completed',
+      output: [{ type: 'message', content: [{ type: 'refusal', refusal: 'No' }] }],
+      output_text: '',
+    });
+    await expect(service.requestJson('data', 'Return JSON')).rejects.toThrow('declined');
+  });
+});
