+  private async requestJson(prompt: string, instructions: string) {
+    // Each workflow previously used a fresh server-side thread. Keep that
+    // isolation with a fresh Conversation, without sharing singleton state.
+    const conversation = await this.threadConversation();
+    const response = await this.openai.responses.create({
+      model: 'gpt-4o',
+      conversation: conversation.id,
+      instructions,
+      input: [{ role: 'user', content: prompt }],
+      text: { format: { type: 'json_object' } },
+      stream: false,
+    });
+    if (response.status !== 'completed') {
+      throw new Error(`AI response did not complete: ${response.status}`);
+    }
+    if (
+      response.output.some(
+        (item) =>
+          item.type === 'message' &&
+          item.content.some((content) => content.type === 'refusal'),
+      )
+    ) {
+      throw new Error('AI declined the request');
+    }
+    if (!response.output_text) {
+      throw new Error('AI response contained no text');
+    }
+    let result: any;
+    try {
+      result = JSON.parse(response.output_text);
+    } catch {
+      throw new Error('Failed to parse JSON response from AI');
+    }
+    if (!result || typeof result !== 'object' || Array.isArray(result)) {
+      throw new Error('AI response must be a JSON object');
+    }
+    return result;
+  }
