--- /dev/null
+++ b/pages/api/openai.js
@@ -0,0 +1,46 @@
+import OpenAI from "openai";
+
+export default async function handler(req, res) {
+  if (req.method !== "POST") {
+    res.setHeader("Allow", "POST");
+    return res.status(405).json({ error: "Method not allowed" });
+  }
+
+  const { action, prompt } = req.body || {};
+  if (
+    !["text", "image"].includes(action) ||
+    typeof prompt !== "string" ||
+    !prompt.trim()
+  ) {
+    return res.status(400).json({ error: "A valid action and prompt are required" });
+  }
+
+  if (!process.env.OPENAI_API_KEY) {
+    return res.status(503).json({ error: "OpenAI is not configured" });
+  }
+
+  try {
+    const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
+    if (action === "text") {
+      const response = await openai.responses.create({
+        model: "gpt-5.6-terra",
+        input: prompt,
+        max_output_tokens: 500,
+      });
+      return res.status(200).json({ value: response.output_text });
+    }
+
+    const result = await openai.images.generate({
+      prompt,
+      n: 1,
+      size: "256x256",
+    });
+    const url = result.data?.[0]?.url;
+    if (!url) {
+      throw new Error("Image response did not contain a URL");
+    }
+    return res.status(200).json({ value: url });
+  } catch {
+    return res.status(502).json({ error: "OpenAI request failed" });
+  }
+}

