diff --git a/lib/openai-text.js b/lib/openai-text.js
new file mode 100644
index 0000000000000000000000000000000000000000..47787254f1da6ac871e8850bb0234e2a035b6169
--- /dev/null
+++ b/lib/openai-text.js
@@ -0,0 +1,22 @@
+import OpenAI from 'openai';
+
+/** Generate plain text using the current OpenAI Responses API. */
+export async function generateOpenAIText({input, instructions}) {
+  // Resolve credentials at request time so missing configuration does not
+  // prevent plugins from loading or reaching their existing fallbacks.
+  const client = new OpenAI({
+    apiKey: global.openai_key,
+    organization: global.openai_org_id || undefined,
+  });
+  const response = await client.responses.create({
+    model: 'gpt-5.6-terra',
+    input,
+    ...(instructions ? {instructions} : {}),
+    store: false,
+  });
+  const text = response.output_text?.trim();
+  if (response.status !== 'completed' || !text || text === 'error') {
+    throw new Error('OpenAI did not return a completed text response');
+  }
+  return text;
+}
